#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8
ZONE="emilianocasijr.com"
REPO="v1be-coding/v1be-infra"
WORKFLOW=".github/workflows/deploy.yml"
DRAFT="/c/code/v1be-infra/.drafts/deploy.yml"
# Stops Git Bash rewriting the paths passed to gh api.
export MSYS_NO_PATHCONV=1

# GitHub owner and Cloudflare logins stay in Windows Sandbox (ADR-0012).
if [[ ! -d /c/code/v1be-infra/sandbox ]]; then
  warn "Stopping: this isn't Windows Sandbox. Open v1be-admin.wsb and run it there."
  exit 1
fi

# cf PATH calls Cloudflare's API. The header goes through stdin, not the arguments.
cf() {
  printf 'Authorization: Bearer %s' "$CF_TOKEN" \
    | curl -s -H @- "https://api.cloudflare.com/client/v4/$1" | tr -d '\r' || true
}

start_run() {
  gh workflow run deploy.yml --repo "$REPO" --ref main
  note "Waiting for GitHub to start the run."
  sleep 8
  RUN_ID="$(gh run list --repo "$REPO" --workflow deploy.yml --limit 1 --json databaseId --jq '.[0].databaseId' | tr -d '\r')"
  open_url "https://github.com/$REPO/actions/runs/$RUN_ID"
}

job_field() { # job name, field
  gh api "repos/$REPO/actions/runs/$RUN_ID/jobs" \
    --jq ".jobs[] | select(.name == \"$1\") | .$2" 2>/dev/null | tr -d '\r' || true
}

wait_for_job() { # job name. Fails unless the job succeeds.
  local tries=0
  until [[ "$(job_field "$1" status)" == "completed" ]]; do
    (( ++tries > 120 )) && { warn "Stopping: the $1 job took over 20 minutes."; exit 1; }
    sleep 10
  done
  if [[ "$(job_field "$1" conclusion)" != "success" ]]; then
    warn "The $1 job failed. Stopping. Copy its error from the public log for Claude."
    exit 1
  fi
  say "PASS: the $1 job finished"
}

# Reads a job's public log and looks for anything shaped like the secret: 64
# letters and digits. Plain hex is left out, because that's Terraform's checksum.
# It prints only a count, so the value can't reach this screen.
scan_log() { # job name
  local id hits
  id="$(job_field "$1" id)"
  # Logs hold colour codes, which gh refuses to output by default. This only goes
  # into a variable, and the codes are stripped before anything reads it.
  JOB_LOG="$(gh api --allow-escape-sequences "repos/$REPO/actions/jobs/$id/logs" \
    | tr -d '\r' | sed -E 's/\x1b\[[0-9;]*[A-Za-z]//g')"
  if [[ -z "$JOB_LOG" ]]; then
    warn "Stopping: couldn't read the $1 log, so nothing is proven."
    exit 1
  fi
  hits="$(grep -oE '[A-Za-z0-9]{64,}' <<<"$JOB_LOG" | grep -vcE '^[0-9a-f]+$' || true)"
  if [[ "$hits" != "0" ]]; then
    warn "FAIL: the $1 log has $hits string(s) shaped like the secret."
    gh run cancel "$RUN_ID" --repo "$REPO" >/dev/null 2>&1 || true
    sleep 5
    gh run delete "$RUN_ID" --repo "$REPO" || warn "Delete run $RUN_ID by hand, now."
    warn "Stopping. The run is cancelled and deleted. Tell Claude only that this failed."
    exit 1
  fi
  say "PASS: nothing shaped like the secret in the $1 log"
}

banner "Set up the edge stack's CI, and run it for the first time"

stage "Before you start"
say "This gives CI the Cloudflare token, adds the deploy workflow, and runs edge."
step "Merge the PR that adds stacks/edge first."
step "Have the $ZONE token, v1be-infra-edge, open in your password manager."
note "Nothing changes in Cloudflare or AWS until you approve the apply in stage 6."
pause

stage "Sign in to GitHub"
step "Sign in with your own GitHub account, the org owner, not v1be-bot."
gh auth status >/dev/null 2>&1 || gh auth login --hostname github.com --git-protocol https --web --scopes admin:org,repo,workflow
ORG_ROLE="$(gh api user/memberships/orgs/v1be-coding --jq .role 2>/dev/null | tr -d '\r' || true)"
if [[ "$ORG_ROLE" != "admin" ]]; then
  warn "Stopping: this GitHub login isn't a v1be-coding owner."
  exit 1
fi
if ! gh api "repos/$REPO/contents/stacks/edge/main.tf" >/dev/null 2>&1; then
  warn "Stopping: stacks/edge isn't on main yet. Merge its PR first."
  exit 1
fi
for environment in plan apply; do
  for name in PORTFOLIO_ACCOUNT_ID CAFE_ACCOUNT_ID; do
    if ! gh secret list --repo "$REPO" --env "$environment" | grep -q "^$name"; then
      warn "Stopping: $name is missing from $environment. Run oidc-check.sh first."
      exit 1
    fi
  done
done
say "PASS: signed in, edge is on main, and both environments have the account IDs"
pause

stage "Check the zone, then store the token"
if gh secret list --repo "$REPO" --env apply | grep -q "^CLOUDFLARE_API_TOKEN" \
  && confirm "The token is already stored. Skip this stage?"; then
  say "Skipped: using the stored token."
else
say "Copy the token, then paste it here. It's hidden, so you won't see anything."
step "To paste in Git Bash: right-click, or Shift+Insert. Ctrl+V doesn't work."
CF_TOKEN=""
ask_secret CF_TOKEN "Cloudflare token" || true
CF_TOKEN="${CF_TOKEN//[[:space:]]/}"
if [[ -z "$CF_TOKEN" ]]; then
  warn "Stopping: nothing was pasted."
  exit 1
fi
ZONE_JSON="$(cf "zones?name=$ZONE")"
ZONE_ID="$(grep -oE '"id": *"[0-9a-f]{32}"' <<<"$ZONE_JSON" | head -1 | grep -oE '[0-9a-f]{32}' || true)"
if [[ -z "$ZONE_ID" ]]; then
  unset CF_TOKEN
  warn "Stopping: the token can't see $ZONE."
  exit 1
fi
say "PASS: the token sees $ZONE"
note "The origin header goes to every proxied hostname, so each must point at AWS."
PROXIED="$(cf "zones/$ZONE_ID/dns_records?proxied=true&per_page=100" \
  | grep -oE '"name": *"[^"]*"' | sed -E 's/.*: *"(.*)"/\1/' || true)"
if [[ -n "$PROXIED" ]]; then
  warn "Stopping: these hostnames are proxied today:"
  note "$PROXIED"
  note "Tell Claude these names, and where each one points."
  unset CF_TOKEN
  exit 1
fi
say "PASS: no proxied hostnames yet"
note "Terraform can't create a rule set for a phase that already has one."
RULESETS="$(cf "zones/$ZONE_ID/rulesets")"
if ! grep -Eq '"success": *true' <<<"$RULESETS"; then
  unset CF_TOKEN
  warn "Stopping: couldn't list the zone's rule sets. Tell Claude."
  exit 1
fi
TAKEN="$(grep -oE '"phase": *"(http_ratelimit|http_request_late_transform|http_request_cache_settings)"' <<<"$RULESETS" || true)"
if [[ -n "$TAKEN" ]]; then
  unset CF_TOKEN
  warn "Stopping: the zone already has rules in these phases:"
  note "$TAKEN"
  note "Tell Claude these lines. They'll need importing, and nothing has changed."
  exit 1
fi
say "PASS: those phases are free"
for environment in plan apply; do
  printf '%s' "$CF_TOKEN" | gh secret set CLOUDFLARE_API_TOKEN --repo "$REPO" --env "$environment"
done
unset CF_TOKEN ZONE_JSON RULESETS
say "PASS: token stored on plan and apply"
fi
pause

stage "Add the workflow"
if gh api "repos/$REPO/contents/$WORKFLOW" >/dev/null 2>&1; then
  say "It's already on main."
else
  step "Read $DRAFT first."
  confirm "Open a PR adding it?" || { warn "Stopping. Run this again when ready."; exit 1; }
  MAIN_SHA="$(gh api "repos/$REPO/git/ref/heads/main" --jq .object.sha | tr -d '\r')"
  gh api -X POST "repos/$REPO/git/refs" -f "ref=refs/heads/add-deploy-workflow" -f "sha=$MAIN_SHA" >/dev/null
  gh api -X PUT "repos/$REPO/contents/$WORKFLOW" -f "message=Add the deploy workflow" \
    -f "branch=add-deploy-workflow" -f "content=$(base64 -w0 "$DRAFT")" >/dev/null
  PR_URL="$(gh pr create --repo "$REPO" --head add-deploy-workflow --base main \
    --title "Add the deploy workflow" --body "Plans and applies edge after a merge (phase D)." | tr -d '\r')"
  open_url "$PR_URL"
  step "Wait for risky-text, then merge the PR in the browser."
  pause "Press Enter once it's merged."
fi
pause

stage "Run the plan alone"
RUN_ID="$(gh run list --repo "$REPO" --workflow deploy.yml --status waiting --limit 1 --json databaseId --jq '.[0].databaseId // ""' | tr -d '\r')"
if [[ -n "$RUN_ID" ]]; then
  say "Using the run that's already waiting for approval."
  open_url "https://github.com/$REPO/actions/runs/$RUN_ID"
else
  start_run
fi
note "The workflow's plan job is running. This waits for it."
wait_for_job plan
scan_log plan
if ! grep -q 'Plan: 13 to add, 0 to change, 0 to destroy' <<<"$JOB_LOG"; then
  warn "The plan isn't the expected 13 to add. Don't approve it. Tell Claude its Plan line."
  exit 1
fi
say "PASS: the plan adds 13 things and removes nothing"
note "The secret doesn't exist yet, so this can't prove it stays hidden once real."
note "Stages 6 and 7 scan the logs again, after it exists."
step "Read the plan in the browser, in the 'terraform plan' step."
pause

stage "Approve the apply"
step "In the browser, select Review deployments, tick apply, then Approve."
warn "This is the step that changes Cloudflare and AWS."
wait_for_job apply
scan_log apply
pause

stage "Run a second plan"
start_run
note "This shows nothing drifted, and the secret stays hidden now that it's real."
wait_for_job plan
scan_log plan
if ! grep -q 'No changes\.' <<<"$JOB_LOG"; then
  warn "The second plan shows changes. Don't approve anything. Tell Claude its Plan line."
  exit 1
fi
say "PASS: no changes"
pause

stage "Look at the Cloudflare dashboard"
open_url "https://dash.cloudflare.com/"
step "Open $ZONE."
say "Check all of these are there:"
note "  SSL/TLS, Overview:     Full (strict)"
note "  Rules, Overview:       v1be origin header, v1be cache bypass"
note "  Security, WAF:         v1be rate limit, under Rate limiting rules"
confirm "Do you see all of them?" || { warn "Tell Claude which one is missing."; exit 1; }
pause

finish
say "Tell Claude that the second plan showed no changes and the rules are there."
note "Don't share the token."
}

run_wizard "$@"; exit
